/**
 * The contract check — #werk-contract. Every path that sets a card to decided runs it:
 * `status` and `rederive --status decided` (#werk-contract-when). Fails with the command
 * that fixes each missing fact.
 */
function contract(id: string): void {
  const { g, node } = requireNode(id)
  const problems: string[] = []
  // A ghost's own edges are held, not live. The contract still has to see them, or a
  // card could only be proposed as open and would need a second turn to become decided.
  const visible = node.proposed ? [...g.edges, ...g.ghostEdges] : g.edges
  if (!node.who) {
    problems.push(`who is not set. Run:\n      node src/cli.ts edit ${id} --who you|me|prototype`)
  }
  const hasBasis = visible.some((e) => e.from === id && e.type === 'depends_on')
  if (!hasBasis && !node.noBasis) {
    problems.push(
      `no depends_on edge, and --no-basis is not on record. Run one of:\n` +
        `      node src/cli.ts link ${id} <parent-id> --type depends_on --why "..."\n` +
        `      node src/cli.ts edit ${id} --no-basis`,
    )
  }
  if (node.who === 'you') {
      console.log(`${id} is open again. ${stale.length} card(s) went stale:`)
      for (const s of stale) console.log(`  ${s}`)
    }
    break
  }

  case 'rederive': {
    const id = positional[0] ?? fail('rederive needs an id')
    const { node } = requireNode(id)
    const status = str(flags, 'status')
    if (status !== undefined && !['decided', 'open', 'proto'].includes(status)) fail('--status must be decided, open, or proto')
    if (status === 'decided' && node.kind === 'card') contract(id)
    append('rederived', { id, status }, { actor: actor(flags) })
    console.log(`${id} is up to date. ${graph().stale.size} card(s) still stale.`)
    break
  }

  case 'move': {
    const id = positional[0] ?? fail('move needs an id')
    const parent = str(flags, 'parent') ?? fail('move needs --parent')
    requireNode(id)
    requireNode(parent)
    append('level.moved', { id, parent }, { actor: actor(flags) })
    console.log(`${id} now refines ${parent}`)
    break
  }
  el('crumbs').innerHTML =
    chain
      .map((c) => `<button class="crumb" data-go="${esc(c)}">${esc(titleOf(node(c)))}</button>`)
      .concat(`<span class="crumb now">${esc(titleOf(n))}</span>`)
      .join('<span class="sep">›</span>')

  // The header counts the whole map, whatever card you are on.
  el('counts').innerHTML = rollupLine(rollup('root'), 'whole map,')

  const alarms = []
  if (G.stale.has(id)) {
    alarms.push(`<div class="alarm red"><b>Stale.</b> A card this one depends on was reopened. Re-derive it or change it.</div>`)
  } else if (G.paused.has(id)) {
    alarms.push(`<div class="alarm gray"><b>Paused.</b> A card this one depends on was postponed, not invalidated. It still holds.</div>`)
  }

